<?php
if(!defined('ABSPATH')){exit;}if(!current_user_can(SPF_Roles::CUSTOMERS)&&!current_user_can('manage_options')){wp_die(esc_html__('No tienes permisos para gestionar clientes.','sistema-para-farmacias'));}global $wpdb;$customers=SPF_Database::table('customers');$sales=SPF_Database::table('sales');$documents=array_merge(SPF_Config::person_documents(),SPF_Config::business_documents());if(!$documents){$documents=['GENERIC'=>__('Documento','sistema-para-farmacias')];}$edit_id=absint($_GET['edit_customer']??0);$editing=$edit_id?$wpdb->get_row($wpdb->prepare("SELECT * FROM $customers WHERE id=%d",$edit_id),ARRAY_A):null;$q=sanitize_text_field(wp_unslash($_GET['s']??''));$where='1=1';$params=[];if($q!==''){$like='%'.$wpdb->esc_like($q).'%';$where.=' AND (c.name LIKE %s OR c.business_name LIKE %s OR c.document_number LIKE %s OR c.email LIKE %s OR c.phone LIKE %s)';$params=[$like,$like,$like,$like,$like];}$sql="SELECT c.*,COUNT(s.id) sales_count,COALESCE(SUM(s.total),0) total_spent,MAX(s.created_at) last_sale FROM $customers c LEFT JOIN $sales s ON s.customer_id=c.id WHERE $where GROUP BY c.id ORDER BY c.id DESC LIMIT 300";$rows=$params?$wpdb->get_results($wpdb->prepare($sql,...$params),ARRAY_A):$wpdb->get_results($sql,ARRAY_A);$customer=$editing?:[];$notice=sanitize_key($_GET['spf_notice']??'');$type=sanitize_key($_GET['spf_notice_type']??'success');$messages=['created'=>__('Cliente creado.','sistema-para-farmacias'),'updated'=>__('Cliente actualizado.','sistema-para-farmacias'),'deleted'=>__('Cliente eliminado.','sistema-para-farmacias'),'missing_name'=>__('Ingresa nombre o razón social.','sistema-para-farmacias'),'duplicate_document'=>__('Ya existe un cliente con ese número de documento.','sistema-para-farmacias'),'customer_used'=>__('No se puede eliminar porque tiene ventas asociadas; el historial debe conservarse.','sistema-para-farmacias')];if($notice&&isset($messages[$notice])){echo '<div class="notice notice-'.($type==='error'?'error':'success').' is-dismissible"><p>'.esc_html($messages[$notice]).'</p></div>';}?>
<div class="wrap spf-wrap"><h1><?php esc_html_e('Clientes','sistema-para-farmacias'); ?></h1><div class="spf-panel"><h2><?php echo esc_html($editing?__('Editar cliente','sistema-para-farmacias'):__('Crear cliente','sistema-para-farmacias')); ?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="spf-grid-form"><?php wp_nonce_field('spf_save_customer'); ?><input type="hidden" name="action" value="spf_save_customer"><input type="hidden" name="customer_id" value="<?php echo esc_attr($customer['id']??0); ?>"><label><?php esc_html_e('Tipo documento','sistema-para-farmacias'); ?><select name="document_type"><?php foreach($documents as $code=>$label): ?><option value="<?php echo esc_attr($code); ?>" <?php selected($customer['document_type']??array_key_first($documents),$code); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><label><?php esc_html_e('Número documento','sistema-para-farmacias'); ?><input name="document_number" value="<?php echo esc_attr($customer['document_number']??''); ?>"></label><label><?php esc_html_e('Nombre','sistema-para-farmacias'); ?><input name="name" value="<?php echo esc_attr($customer['name']??''); ?>"></label><label><?php esc_html_e('Razón social','sistema-para-farmacias'); ?><input name="business_name" value="<?php echo esc_attr($customer['business_name']??''); ?>"></label><label><?php esc_html_e('Dirección','sistema-para-farmacias'); ?><input name="address" value="<?php echo esc_attr($customer['address']??''); ?>"></label><label><?php esc_html_e('Email','sistema-para-farmacias'); ?><input name="email" type="email" value="<?php echo esc_attr($customer['email']??''); ?>"></label><label><?php esc_html_e('Teléfono','sistema-para-farmacias'); ?><input name="phone" value="<?php echo esc_attr($customer['phone']??''); ?>"></label><div class="spf-form-actions"><button class="button button-primary"><?php echo esc_html($editing?__('Actualizar cliente','sistema-para-farmacias'):__('Guardar cliente','sistema-para-farmacias')); ?></button><?php if($editing): ?><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=spf-customers')); ?>"><?php esc_html_e('Cancelar','sistema-para-farmacias'); ?></a><?php endif; ?></div></form></div><div class="spf-panel"><form method="get" class="spf-form-actions"><input type="hidden" name="page" value="spf-customers"><input name="s" value="<?php echo esc_attr($q); ?>" placeholder="<?php esc_attr_e('Buscar cliente o documento','sistema-para-farmacias'); ?>"><button class="button"><?php esc_html_e('Buscar','sistema-para-farmacias'); ?></button><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=spf-customers')); ?>"><?php esc_html_e('Limpiar','sistema-para-farmacias'); ?></a></form></div><div class="spf-panel"><div class="spf-table-scroll"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Documento','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Cliente','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Contacto','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Ventas','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Total comprado','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Última venta','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Acciones','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7"><?php esc_html_e('No hay clientes registrados.','sistema-para-farmacias'); ?></td></tr><?php endif; ?><?php foreach($rows as $row): ?><tr><td><strong><?php echo esc_html($documents[$row['document_type']]??$row['document_type']); ?></strong><br><?php echo esc_html($row['document_number']); ?></td><td><strong><?php echo esc_html($row['business_name']?:$row['name']); ?></strong><br><small><?php echo esc_html($row['address']); ?></small></td><td><?php echo esc_html($row['email']); ?><br><small><?php echo esc_html($row['phone']); ?></small></td><td><?php echo esc_html((int)$row['sales_count']); ?></td><td><strong><?php echo esc_html(SPF_Config::money($row['total_spent'])); ?></strong></td><td><?php echo esc_html($row['last_sale']?:'—'); ?></td><td><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=spf-customers&edit_customer='.(int)$row['id'])); ?>"><?php esc_html_e('Editar','sistema-para-farmacias'); ?></a><?php if((int)$row['sales_count']===0): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" style="display:inline" onsubmit="return confirm('<?php echo esc_js(__('¿Eliminar este cliente?','sistema-para-farmacias')); ?>')"><?php wp_nonce_field('spf_delete_customer'); ?><input type="hidden" name="action" value="spf_delete_customer"><input type="hidden" name="customer_id" value="<?php echo esc_attr($row['id']); ?>"><button class="button"><?php esc_html_e('Eliminar','sistema-para-farmacias'); ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
